typedef int (*Operation)(int, int);
int add(int a, int b) { return a + b; }
int subtract(int a, int b) { return a - b; }
int execute_operation(Operation op, int x, int y) {
    return op(x, y);
}
int main() {
    Operation op = add; // Assign function pointer to 'add'
    int result1 = execute_operation(op, 5, 3);
    op = subtract; // Change to 'subtract' at runtime
    int result2 = execute_operation(op, 5, 3);
    return 0;
}
